// Timeline is an underdocumented and under explored function, I think there
// are a lot of possibilities for live use ! Like switching/transitioning 
// between song parts, or doing 'drops'.

// Here's a basic example! First here's a couple of simple extra functions

// 'open' is a continuous signal that goes from 0 to 1 and then stays 
// on 1 forever
const open = signal(t => Math.min(t, 1));

// 'close' is similar but goes from 1 to 0 and stays on 0
const close = signal(t => Math.max(1 - t, 0));


